def findFarmland(land):
    rows, cols = len(land), len(land[0])
    result = []
    for r in range(rows):
        for c in range(cols):
            if land[r][c] != 1:
                continue
            if r > 0 and land[r - 1][c] == 1:
                continue
            if c > 0 and land[r][c - 1] == 1:
                continue
            r2, c2 = r, c
            while r2 + 1 < rows and land[r2 + 1][c] == 1:
                r2 += 1
            while c2 + 1 < cols and land[r][c2 + 1] == 1:
                c2 += 1
            result.append([r, c, r2, c2])
    return result
